function Get-SystemHealthCheck { [CmdletBinding()]param();$keys=@('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending','HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')|Where-Object {Test-Path $_};[pscustomobject]@{PendingRestart=[bool]$keys;Defender=(Get-MpComputerStatus -ErrorAction SilentlyContinue|Select-Object AMServiceEnabled,AntivirusEnabled,RealTimeProtectionEnabled);Firewall=(Get-NetFirewallProfile -ErrorAction SilentlyContinue|Select-Object Name,Enabled)} }